css:
.toggle {
  --bg-red: red;
  --bg-green: #0c7839;
  --shadow-red: rgba(240, 46, 46, 0.4);
  --shadow-green: rgba(36, 157, 10, 0.4);
  --knob-color: #ff4d4d;

  font-size: 17px;
  position: relative;
  display: inline-block;
  appearance: none;
  width: 7.65em;
  height: 3.53em;
  border-radius: 3em;
  background-color: var(--bg-red);
  cursor: pointer;
  outline: none;
  border: none;

  box-shadow:
    var(--shadow-red) -0.3em 0.3em,
    rgba(240, 46, 46, 0.3) -0.6em 0.6em,
    rgba(240, 46, 46, 0.2) -0.9em 0.9em,
    rgba(240, 46, 46, 0.1) -1.2em 1.2em,
    rgba(240, 46, 46, 0.05) -1.5em 1.5em;

  transition: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.toggle:after {
  content: "✕";
  color: var(--knob-color);
  font-weight: bold;
  position: absolute;
  width: 2.94em;
  height: 2.94em;
  background: white;
  border-radius: 50%;
  left: 0.3em;
  top: 0.3em;
  display: flex;
  align-items: center;
  justify-content: center;

  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
  transition: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.toggle:checked {
  background-color: var(--bg-green);
  box-shadow:
    var(--shadow-green) 0.3em 0.3em,
    rgba(36, 157, 10, 0.3) 0.6em 0.6em,
    rgba(36, 157, 10, 0.2) 0.9em 0.9em,
    rgba(36, 157, 10, 0.1) 1.2em 1.2em,
    rgba(36, 157, 10, 0.05) 1.5em 1.5em;
}

.toggle:checked:after {
  content: "✓";
  color: green;
  left: 4.41em;
  transform: rotate(360deg);
}

.toggle:focus-visible {
  outline: 2px solid #444;
  outline-offset: 10px;
}

.toggle:hover {
  filter: brightness(1.1);
}

.toggle:active {
  transform: scale(0.96);
}
